package br.ufpa.dsai.estilomarcado.catalogo;

import static org.hamcrest.Matchers.hasSize;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.patch;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.ResultActions;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import com.fasterxml.jackson.databind.ObjectMapper;

import br.ufpa.dsai.estilomarcado.catalogo.model.Profissional;
import br.ufpa.dsai.estilomarcado.catalogo.model.Unidade;
import br.ufpa.dsai.estilomarcado.catalogo.repository.ProfissionalRepository;
import br.ufpa.dsai.estilomarcado.catalogo.repository.ServicoRepository;
import br.ufpa.dsai.estilomarcado.catalogo.repository.UnidadeRepository;

@SpringBootTest
@AutoConfigureMockMvc
@Testcontainers
class ServicoCatalogIntegrationTest {

    @Container
    @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:17-alpine");

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Autowired
    JdbcTemplate jdbcTemplate;

    @Autowired
    UnidadeRepository unidadeRepository;

    @Autowired
    ProfissionalRepository profissionalRepository;

    @Autowired
    ServicoRepository servicoRepository;

    private Unidade unidade;
    private Unidade outraUnidade;
    private Profissional profA;
    private Profissional profB;
    private Profissional profOutraUnidade;

    @BeforeEach
    void prepararBanco() {
        jdbcTemplate.execute("DELETE FROM servico_profissional");
        jdbcTemplate.execute("DELETE FROM servico");
        jdbcTemplate.execute("DELETE FROM profissional");
        jdbcTemplate.execute("DELETE FROM unidade");

        unidade = unidadeRepository.save(new Unidade("Unidade Centro"));
        outraUnidade = unidadeRepository.save(new Unidade("Unidade Norte"));
        profA = profissionalRepository.save(new Profissional("Ana", unidade));
        profB = profissionalRepository.save(new Profissional("Bruno", unidade));
        profOutraUnidade = profissionalRepository.save(new Profissional("Carlos", outraUnidade));
    }

    @Test
    void deveCriarServicoComDadosValidos() throws Exception {
        criarServico(unidade.getId(), servicoValido())
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.id").isNumber())
                .andExpect(jsonPath("$.unidadeId").value(unidade.getId()))
                .andExpect(jsonPath("$.nome").value("Corte de cabelo"))
                .andExpect(jsonPath("$.duracaoMinutos").value(30))
                .andExpect(jsonPath("$.ativo").value(true));
    }

    @Test
    void deveRejeitarServicoSemNome() throws Exception {
        Map<String, Object> body = servicoValido();
        body.remove("nome");
        criarServico(unidade.getId(), body).andExpect(status().isBadRequest());
    }

    @Test
    void deveRejeitarServicoSemDuracao() throws Exception {
        Map<String, Object> body = servicoValido();
        body.remove("duracaoMinutos");
        criarServico(unidade.getId(), body).andExpect(status().isBadRequest());
    }

    @Test
    void deveRejeitarDuracaoZeroOuNegativa() throws Exception {
        criarServico(unidade.getId(), servicoValidoCom("duracaoMinutos", 0))
                .andExpect(status().isBadRequest());
        criarServico(unidade.getId(), servicoValidoCom("duracaoMinutos", -5))
                .andExpect(status().isBadRequest());
    }

    @Test
    void deveRejeitarPrecoNegativo() throws Exception {
        criarServico(unidade.getId(), servicoValidoCom("preco", new BigDecimal("-1.00")))
                .andExpect(status().isBadRequest());
    }

    @Test
    void deveRejeitarPrecoComMaisDeDuasCasasDecimais() throws Exception {
        criarServico(unidade.getId(), servicoValidoCom("preco", new BigDecimal("10.999")))
                .andExpect(status().isBadRequest());
    }

    @Test
    void deveAceitarIntervaloNulo() throws Exception {
        criarServico(unidade.getId(), servicoValido())
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.intervaloMinutos").doesNotExist());
    }

    @Test
    void deveRejeitarIntervaloNegativo() throws Exception {
        criarServico(unidade.getId(), servicoValidoCom("intervaloMinutos", -1))
                .andExpect(status().isBadRequest());
    }

    @Test
    void deveAssociarProfissionaisDaMesmaUnidade() throws Exception {
        Map<String, Object> body = servicoValido();
        body.put("profissionalIds", List.of(profA.getId(), profB.getId()));
        criarServico(unidade.getId(), body)
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.profissionais", hasSize(2)));
    }

    @Test
    void deveRejeitarProfissionalDeOutraUnidade() throws Exception {
        Map<String, Object> body = servicoValido();
        body.put("profissionalIds", List.of(profOutraUnidade.getId()));
        criarServico(unidade.getId(), body).andExpect(status().isUnprocessableEntity());
    }

    @Test
    void deveRejeitarNomeDuplicadoNaMesmaUnidade() throws Exception {
        criarServico(unidade.getId(), servicoValido()).andExpect(status().isCreated());
        criarServico(unidade.getId(), servicoValido()).andExpect(status().isConflict());
    }

    @Test
    void devePermitirMesmoNomeEmUnidadesDiferentes() throws Exception {
        criarServico(unidade.getId(), servicoValido()).andExpect(status().isCreated());
        criarServico(outraUnidade.getId(), servicoValido()).andExpect(status().isCreated());
    }

    @Test
    void servicoSemProfissionalNaoApareceComoDisponivel() throws Exception {
        criarServico(unidade.getId(), servicoValido()).andExpect(status().isCreated());

        mockMvc.perform(get("/api/unidades/{unidadeId}/servicos", unidade.getId())
                        .param("somenteDisponiveis", "true"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$", hasSize(0)));
    }

    @Test
    void servicoDesativadoNaoApareceComoDisponivelMasPermaneceNaListagem() throws Exception {
        Map<String, Object> body = servicoValido();
        body.put("profissionalIds", List.of(profA.getId()));
        String resposta = criarServico(unidade.getId(), body)
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();

        Long id = objectMapper.readTree(resposta).get("id").asLong();

        mockMvc.perform(patch("/api/servicos/{id}/desativar", id))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.ativo").value(false));

        mockMvc.perform(get("/api/unidades/{unidadeId}/servicos", unidade.getId())
                        .param("somenteDisponiveis", "true"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$", hasSize(0)));

        mockMvc.perform(get("/api/unidades/{unidadeId}/servicos", unidade.getId()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$", hasSize(1)))
                .andExpect(jsonPath("$[0].ativo").value(false));
    }

    @Test
    void desativarNaoRemoveFisicamenteOservico() throws Exception {
        criarServico(unidade.getId(), servicoValido()).andExpect(status().isCreated());

        Long id = servicoRepository.findAll().get(0).getId();

        mockMvc.perform(patch("/api/servicos/{id}/desativar", id))
                .andExpect(status().isOk());

        servicoRepository.findById(id).ifPresentOrElse(
                servico -> org.junit.jupiter.api.Assertions.assertFalse(servico.isAtivo()),
                () -> org.junit.jupiter.api.Assertions.fail("servico nao deveria ser removido fisicamente"));
    }

    @Test
    void naoExisteEndpointDeExclusaoFisica() throws Exception {
        criarServico(unidade.getId(), servicoValido()).andExpect(status().isCreated());
        Long id = servicoRepository.findAll().get(0).getId();

        mockMvc.perform(delete("/api/servicos/{id}", id))
                .andExpect(status().isMethodNotAllowed());
    }

    @Test
    void buscarServicoInexistenteRetorna404() throws Exception {
        mockMvc.perform(get("/api/servicos/999999"))
                .andExpect(status().isNotFound());
    }

    private Map<String, Object> servicoValido() {
        return new java.util.HashMap<>(Map.of(
                "nome", "Corte de cabelo",
                "descricao", "Corte com tesoura e maquina",
                "duracaoMinutos", 30,
                "preco", new BigDecimal("50.00")
        ));
    }

    private Map<String, Object> servicoValidoCom(String campo, Object valor) {
        Map<String, Object> body = servicoValido();
        body.put(campo, valor);
        return body;
    }

    private ResultActions criarServico(Long unidadeId, Map<String, Object> body) throws Exception {
        return mockMvc.perform(post("/api/unidades/{unidadeId}/servicos", unidadeId)
                .contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(body)));
    }
}

package br.ufpa.dsai.estilomarcado.catalogo.service;

import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import br.ufpa.dsai.estilomarcado.catalogo.api.dto.ServicoRequest;
import br.ufpa.dsai.estilomarcado.catalogo.api.dto.ServicoResponse;
import br.ufpa.dsai.estilomarcado.catalogo.api.exception.ConflitoException;
import br.ufpa.dsai.estilomarcado.catalogo.api.exception.RecursoNaoEncontradoException;
import br.ufpa.dsai.estilomarcado.catalogo.api.exception.RegraDeNegocioException;
import br.ufpa.dsai.estilomarcado.catalogo.model.Profissional;
import br.ufpa.dsai.estilomarcado.catalogo.model.Servico;
import br.ufpa.dsai.estilomarcado.catalogo.model.Unidade;
import br.ufpa.dsai.estilomarcado.catalogo.repository.ProfissionalRepository;
import br.ufpa.dsai.estilomarcado.catalogo.repository.ServicoRepository;
import br.ufpa.dsai.estilomarcado.catalogo.repository.UnidadeRepository;

@Service
public class ServicoService {

    private final ServicoRepository servicoRepository;
    private final UnidadeRepository unidadeRepository;
    private final ProfissionalRepository profissionalRepository;

    public ServicoService(ServicoRepository servicoRepository,
                          UnidadeRepository unidadeRepository,
                          ProfissionalRepository profissionalRepository) {
        this.servicoRepository = servicoRepository;
        this.unidadeRepository = unidadeRepository;
        this.profissionalRepository = profissionalRepository;
    }

    @Transactional
    public ServicoResponse criar(Long unidadeId, ServicoRequest request) {
        Unidade unidade = unidadeRepository.findById(unidadeId)
                .orElseThrow(() -> new RecursoNaoEncontradoException("unidade " + unidadeId + " nao encontrada"));

        garantirNomeUnico(unidadeId, request.getNome(), null);

        Servico servico = new Servico(unidade, request.getNome(), request.getDuracaoMinutos(), request.getPreco());
        aplicar(servico, request);
        servico.setAtivo(true);
        servico.substituirProfissionais(resolverProfissionais(unidadeId, request.getProfissionalIds()));

        return ServicoResponse.from(servicoRepository.save(servico));
    }

    @Transactional
    public ServicoResponse atualizar(Long id, ServicoRequest request) {
        Servico servico = buscarEntidade(id);
        garantirNomeUnico(servico.getUnidade().getId(), request.getNome(), id);

        servico.setNome(request.getNome());
        aplicar(servico, request);
        servico.substituirProfissionais(resolverProfissionais(servico.getUnidade().getId(), request.getProfissionalIds()));

        return ServicoResponse.from(servicoRepository.save(servico));
    }

    @Transactional
    public ServicoResponse ativar(Long id) {
        Servico servico = buscarEntidade(id);
        servico.setAtivo(true);
        return ServicoResponse.from(servicoRepository.save(servico));
    }

    @Transactional
    public ServicoResponse desativar(Long id) {
        Servico servico = buscarEntidade(id);
        servico.setAtivo(false);
        return ServicoResponse.from(servicoRepository.save(servico));
    }

    @Transactional(readOnly = true)
    public ServicoResponse buscar(Long id) {
        return ServicoResponse.from(buscarEntidade(id));
    }

    @Transactional(readOnly = true)
    public List<ServicoResponse> listar(Long unidadeId) {
        return servicoRepository.findByUnidadeIdOrderByNomeAsc(unidadeId).stream()
                .map(ServicoResponse::from)
                .toList();
    }

    @Transactional(readOnly = true)
    public List<ServicoResponse> listarDisponiveis(Long unidadeId) {
        return servicoRepository.findDisponiveisPorUnidade(unidadeId).stream()
                .map(ServicoResponse::from)
                .toList();
    }

    private Servico buscarEntidade(Long id) {
        return servicoRepository.findById(id)
                .orElseThrow(() -> new RecursoNaoEncontradoException("servico " + id + " nao encontrado"));
    }

    private void aplicar(Servico servico, ServicoRequest request) {
        servico.setDescricao(request.getDescricao());
        servico.setDuracaoMinutos(request.getDuracaoMinutos());
        servico.setPreco(request.getPreco());
        servico.setIntervaloMinutos(request.getIntervaloMinutos());
    }

    private void garantirNomeUnico(Long unidadeId, String nome, Long idIgnorado) {
        boolean existe;
        if (idIgnorado == null) {
            existe = servicoRepository.existsByUnidadeIdAndNome(unidadeId, nome);
        } else {
            existe = servicoRepository.existsByUnidadeIdAndNomeAndIdNot(unidadeId, nome, idIgnorado);
        }
        if (existe) {
            throw new ConflitoException("ja existe um servico com o nome '" + nome + "' nesta unidade");
        }
    }

    private Set<Profissional> resolverProfissionais(Long unidadeId, Set<Long> profissionalIds) {
        if (profissionalIds == null || profissionalIds.isEmpty()) {
            return new LinkedHashSet<>();
        }

        List<Profissional> profissionais = profissionalRepository.findAllById(profissionalIds);
        if (profissionais.size() != profissionalIds.size()) {
            throw new RecursoNaoEncontradoException("um ou mais profissionais informados nao existem");
        }

        boolean mesmaUnidade = profissionais.stream()
                .allMatch(profissional -> profissional.getUnidade().getId().equals(unidadeId));
        if (!mesmaUnidade) {
            throw new RegraDeNegocioException(
                    "todos os profissionais habilitados devem pertencer a mesma unidade do servico");
        }

        return new LinkedHashSet<>(profissionais);
    }
}

package br.ufpa.dsai.estilomarcado.catalogo.api;

import java.util.List;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import br.ufpa.dsai.estilomarcado.catalogo.api.dto.ServicoRequest;
import br.ufpa.dsai.estilomarcado.catalogo.api.dto.ServicoResponse;
import br.ufpa.dsai.estilomarcado.catalogo.service.ServicoService;
import jakarta.validation.Valid;

@RestController
@RequestMapping("/api")
public class ServicoController {

    private final ServicoService servicoService;

    public ServicoController(ServicoService servicoService) {
        this.servicoService = servicoService;
    }

    @GetMapping("/unidades/{unidadeId}/servicos")
    public List<ServicoResponse> listar(
            @PathVariable Long unidadeId,
            @RequestParam(name = "somenteDisponiveis", defaultValue = "false") boolean somenteDisponiveis) {
        return somenteDisponiveis
                ? servicoService.listarDisponiveis(unidadeId)
                : servicoService.listar(unidadeId);
    }

    @PostMapping("/unidades/{unidadeId}/servicos")
    @ResponseStatus(HttpStatus.CREATED)
    public ServicoResponse criar(@PathVariable Long unidadeId,
                                 @Valid @RequestBody ServicoRequest request) {
        return servicoService.criar(unidadeId, request);
    }

    @GetMapping("/servicos/{id}")
    public ServicoResponse buscar(@PathVariable Long id) {
        return servicoService.buscar(id);
    }

    @PutMapping("/servicos/{id}")
    public ServicoResponse atualizar(@PathVariable Long id,
                                     @Valid @RequestBody ServicoRequest request) {
        return servicoService.atualizar(id, request);
    }

    @PatchMapping("/servicos/{id}/ativar")
    public ServicoResponse ativar(@PathVariable Long id) {
        return servicoService.ativar(id);
    }

    @PatchMapping("/servicos/{id}/desativar")
